'use strict';
// Choices add personal draft lines; they never become reviewed advice.
const originalCommunityPrompts=communityPromptChoices;
let communityPicked={question:null,answer:null};
function liftChoiceLabel(key){return window.LiftChoiceCopy[LiftI18n.locale==='my'?'my':'en'][key];}
function communityChoiceText(key){if(/^(housing|transport|phone|food)[123]$/.test(key))return everydayLabel(key);return ['qHelp','qAsk','qExperience','aNeed','aCompare','aExperience','aUnsure'].includes(key)?liftChoiceLabel(key):null;}
function communityPickedKey(field){const picked=communityPicked[field];return picked&&communityDraft.text.split('\n').some(line=>line.trim()===picked.text)?picked.key:'';}
communityPromptChoices=function(){return `<p class="community-choice-hint">${liftChoiceLabel('pickHint')}</p>`;};
function communityChoiceKeys(){if(communityDraft.kind==='experience')return ['aExperience'];return communityDraft.topic==='daily'?['qHelp','qAsk','qExperience',...['housing','transport','phone','food'].flatMap(topic=>[1,2,3].map(n=>topic+n))]:['qHelp','qAsk','qExperience'];}
function communityChoiceFields(){const c=liftChoiceLabel,field=communityDraft.kind==='experience'?'answer':'question';return `<label for="community-question-choice">${icon('people')}${escapeText(window.LiftWorkflowCopy[LiftI18n.locale==='my'?'my':'en'].chooseStarter)} · ${communityLabel(communityDraft.topic)}</label><select id="community-question-choice" data-draft-choice="${field}"><option value="">${c('choose')}</option>${communityChoiceKeys().map(key=>`<option value="${key}" ${communityPickedKey(field)===key?'selected':''}>${escapeText(communityChoiceText(key))}</option>`).join('')}<option value="other">${c('other')}</option></select><p class="community-choice-hint">${c('optional')}</p>`;}
document.addEventListener('change',event=>{const key=event.target.dataset?.communityField;if(!['kind','topic'].includes(key))return;const owned=Object.values(communityPicked).filter(p=>p?.owned).map(p=>p.text);communityDraft={...communityDraft,text:communityDraft.text.split('\n\n').filter(part=>!owned.includes(part)).join('\n\n')};communityPicked={question:null,answer:null};communityPreview=false;route();document.getElementById('community-'+key)?.focus();});
document.addEventListener('change',e=>{if(!e.target.matches('[data-draft-choice]'))return;const key=e.target.value,field=e.target.dataset?.draftChoice||(key.startsWith('a')?'answer':'question'),previous=communityPicked[field],text=key&&key!=='other'?communityChoiceText(key):'';if(key&&key!=='other'&&!text)return;const next=LiftCommunity.replacePrompt(communityDraft,previous?.owned?previous.text:null,text);if(next.status==='full'){communityFeedback('tooLong');e.target.value=communityPickedKey(field);return;}communityDraft=next.draft;communityPicked[field]=text?{key,text,owned:next.owned}:null;const textarea=document.getElementById?.('community-text'),count=document.getElementById?.('community-limit');if(textarea){textarea.value=communityDraft.text;if(count)count.textContent=communityDraft.text.length+' / 1200';if(key==='other')textarea.focus();}else route();});
// Existing CCO-reviewed survey label, reused without new translation.
Object.assign(window.LiftMyanmar||{}, {'Larger text':"စာလုံးပိုကြီး"});
document.addEventListener('click',e=>{const button=e.target.closest?.('#text-size-button');if(!button)return;const enabled=document.documentElement.classList.toggle('large-myanmar');button.setAttribute('aria-pressed',String(enabled));});
